def source(i,p,t,u,loc,period,pub=None,license=None):
 return dict(sourceId=i,publisher=p,title=t,url=u,locator=loc,version=period,publishedAt=pub,retrievedAt=NOW,reuse=license or dict(basis='Limited factual transcription only; no prose, image, chart or protected presentation reproduced',termsUrl=u,attribution=p+'; '+t,verified=True,notes='No open licence is claimed. This pack contains a small number of numerical facts and original explanatory text.'))
def row(i,name,v,unit,period,s,loc,geo=None,status='estimated',qualifier=None,notes='Source rounded estimate; not a causal AI-impact measure.',**kw):
 return dict(id=i,entityId=i,name=name,value=v,unit=unit,period=period,sourceId=s,sourceLocator=loc,status=status,qualifier=qualifier,geographicId=geo,lat=None,lon=None,notes=notes,**kw)
def dataset(i,title,cids,rows,sources,denom,geo='categorical',geounit='nongeographic categories',definition='Categories are labels, not spatial observations.',limits=[],relationship='context',start=None,end=None,extra=None):
 o=dict(datasetId=i,id=i,title=title,conceptIds=cids,metric=title,unit=rows[0]['unit'] if len(set(r['unit'] for r in rows))==1 else 'mixed; each row is explicitly labelled',denominator=denom,rows=rows,columns=commoncolumns.copy(),geography=dict(mode=geo,unit=geounit,definition=definition,anchorRule='Use true country polygons for ISO-coded rows; use an abstract labelled ring for nongeographic rows. Never scatter aggregate values into cities or invent country intensity.'),time=dict(observationStart=start or rows[0]['period'],observationEnd=end or rows[-1]['period'],publishedAt=sources[0]['publishedAt'],retrievedAt=NOW,updateCadence='Manual reviewed refresh on source revision; never imply a live feed.'),sources=sources,coverage=dict(population=denom,included=str(len(rows))+' explicitly listed records',omitted='All unlisted entities; this extraction is not necessarily exhaustive.',missingness='Null is unknown or unavailable. Absence is not zero.'),uncertainty='Source precision retained. No confidence interval is invented. '+ ' '.join(limits),limitations=limits,aiRelationship=relationship,transform=dict(type='manual',description='Transcribe published factual values; preserve source grain and period.',codePath='research/scripts/society-build.py',inputReferences=[s['url'] for s in sources],validation='Source-locator inspection and schema validation; independent review pending.'),verification=dict(status='researcher-checked',method='Read primary sources and transcribe exact numbers/qualifiers.',checkedRows=[r['id'] for r in rows],evidencePaths=['research/sources/society-research-log.json'],reviewer='/root/society_research',checkedAt=NOW),scoring=dict(type='none',method='none',reason='Show source values; no defensible universal 1–100 AI extremity score.'),forecast=dict(type='none',method='none',reason='No validated prediction model supplied. Do not extrapolate animation into a forecast.'))
 if extra:o.update(extra)
 (D/(i+'.json')).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n');return o
