 c=concepts[cid];ready=candidate.endswith('ready')
 o=dict(conceptId=cid,originalSourceUrl=c['url'],originalQuestion=c['question'],proposedTitle=c['newTitle'],proposedQuestion=question or c['question'],claim=claim,sourceConnection=c['connection'],reframeReason=reason,aiRelationship=dict(**{'class':relationship},justification=claim,sourceIds=[s['sourceId'] for s in sources]),datasetIds=ds,designId=None,verdict='hold' if ready else candidate,candidateVerdict=candidate,blockers=['Independent dataset and design review pending.'] if ready else missing,limitations=missing,scoring=dict(type='none',reason='No comparable, validated 1–100 extremity index.'),forecast=dict(type='none',reason='No validated forecast for this concept.'),review=dict(gates={f'G{i}':dict(status='unchecked',evidence=[],reason='Independent review pending.') for i in range(1,11)},score=None,scoreBreakdown=[],reviewer=None,reviewedAt=None,datasetDigests={}),exactScope=question or claim,rationale=reason or claim,searchedSources=[dict(url=s['url'],finding=s['locator']) for s in sources],missingEvidence=missing)
 AUD.append(o)
